						<text class="status-desc">{{ statusDesc }}</text>
					</view>
				</view>
				<view class="order-no">订单号：{{ orderInfo.orderNo }}</view>
			</view>
			
			<!-- 患者信息 -->
			<view class="info-card">
				<view class="card-title">
					<image class="title-icon" src="/static/ren_1.png" mode="aspectFit"></image>
					<text>患者信息</text>
				</view>
				<view class="patient-info">
					<view class="patient-avatar">
						<image :src="orderInfo.patientAvatar" mode="aspectFill"></image>
					</view>
					<view class="patient-details">
						<view class="patient-name">{{ orderInfo.patientName }}</view>
						<view class="patient-meta">
							<text>{{ orderInfo.patientAge }}岁</text>
							<text>{{ orderInfo.patientGender }}</text>
							<text>{{ orderInfo.patientPhone }}</text>
						</view>
					</view>
					<view class="contact-btn" @click="contactPatient">
						<image src="/static/phone.png" mode="aspectFit"></image>
					</view>
				</view>
			</view>
			
			<!-- 服务信息 -->
			<view class="info-card">
				<view class="card-title">
					<image class="title-icon" src="/static/service.png" mode="aspectFit"></image>
					<text>服务信息</text>
				</view>
				<view class="service-info">
					<view class="info-row">
						<text class="label">服务类型</text>
						<text class="value">{{ orderInfo.serviceType }}</text>
					</view>
					<view class="info-row">
						<text class="label">医院</text>
						<text class="value">{{ orderInfo.hospital }}</text>
					</view>
					<view class="info-row">
						<text class="label">预约时间</text>
						<text class="value">{{ formatAppointmentTime() }}</text>
					</view>
					<view class="info-row" v-if="orderInfo.appointmentEndTime">
						<text class="label">预约结束时间</text>
						<text class="value">{{ orderInfo.appointmentEndTime }}</text>
					</view>
					<view class="info-row" v-if="orderInfo.duration">
						<text class="label">服务时长</text>
						<text class="value">{{ orderInfo.duration }}</text>
					</view>
				</view>
			</view>
			
			<!-- 特殊需求 -->
			<view class="info-card" v-if="orderInfo.specialRequests">
				<view class="card-title">
					<image class="title-icon" src="/static/note.png" mode="aspectFit"></image>
					<text>特殊需求</text>
				</view>
				<view class="special-requests">
					<text>{{ orderInfo.specialRequests }}</text>
				</view>
			</view>
			
			<!-- 费用信息 -->
			<view class="info-card">
				<view class="card-title">
					<image class="title-icon" src="/static/money.png" mode="aspectFit"></image>
					<text>费用信息</text>
				</view>
				<view class="fee-info">
					<view class="fee-row">
						<text class="fee-label">服务费</text>
						<text class="fee-value">¥{{ orderInfo.serviceFee }}</text>
					</view>
					<view class="fee-row" v-if="orderInfo.platformFee">
						<text class="fee-label">平台服务费</text>
						<text class="fee-value">¥{{ orderInfo.platformFee }}</text>
					</view>
					<view class="fee-row total">
						<text class="fee-label">总计</text>
						<text class="fee-value total-price">¥{{ orderInfo.totalFee }}</text>
					</view>
				</view>
			</view>
			
			<!-- 陪诊流程 -->
			<view class="info-card" v-if="orderInfo.status === 'in_progress' || orderInfo.status === 'completed'">
				<view class="card-title">
					<image class="title-icon" src="/static/process.png" mode="aspectFit"></image>
					<text>陪诊流程</text>
				</view>
				<view class="process-timeline">
					<view class="timeline-item" v-for="(step, index) in processSteps" :key="index" :class="{ active: step.completed, current: step.current }">
						<view class="timeline-dot"></view>
						<view class="timeline-content">
							<view class="step-title">{{ step.title }}</view>
							<view class="step-time" v-if="step.time">{{ step.time }}</view>
							<view class="step-desc" v-if="step.desc">{{ step.desc }}</view>
						</view>
					</view>
				</view>
			</view>
			
			<!-- 服务记录 -->
			<view class="info-card" v-if="orderInfo.serviceRecords && orderInfo.serviceRecords.length > 0">
				<view class="card-title">
					<image class="title-icon" src="/static/record.png" mode="aspectFit"></image>
					<text>服务记录</text>
				</view>
				<view class="service-records">
					<view class="record-item" v-for="(record, index) in orderInfo.serviceRecords" :key="index">
						<view class="record-time">{{ record.time }}</view>
						<view class="record-content">{{ record.content }}</view>
					</view>
				</view>
			</view>
		</scroll-view>
		
		<!-- 底部操作按钮 -->
		<view class="bottom-actions" v-if="showActions">
			<button class="action-btn secondary" @click="contactPatient">联系患者</button>
			<button class="action-btn primary" @click="handleMainAction">{{ mainActionText }}</button>
		</view>
	</view>
</template>

<script>
export default {
	data() {
		return {
			isLoading: true,
			orderInfo: {
				id: '',
				orderNo: 'PZ202311150001',
				status: 'accepted', // pending, accepted, in_progress, completed, cancelled
				patientAvatar: '/static/avatar1.png',
				patientName: '患者',
				patientAge: 0,
				patientGender: '',
				patientPhone: '',
				serviceType: '',
				hospital: '',
				appointmentTime: '',
				appointmentEndTime: '',
				duration: '',
				specialRequests: '',
				serviceFee: 0,
				platformFee: 0,
				totalFee: 0,
				serviceRecords: []
			},
			processSteps: [
				{
					title: '前往医院',
					time: '09:00',
					desc: '到达指定地点与患者会合',
					completed: true,
					current: false
				},
				{
					title: '协助挂号',
					time: '09:30',
					desc: '帮助患者完成挂号手续',
					completed: true,
					current: false
				},
				{
					title: '陪同就诊',
					time: '10:00',
					desc: '陪同患者前往科室就诊',
					completed: true,
					current: true
				},
				{
					title: '协助检查',
					desc: '陪同患者完成各项检查',
					completed: false,
					current: false
				},
				{
					title: '取药/报告',
					desc: '协助患者取药或取检查报告',
					completed: false,
					current: false
				},
				{
					title: '服务完成',
					desc: '确认患者安全离开医院',
					completed: false,
					current: false
				}
			]
		}
	},
	
	computed: {
		statusIcon() {
			const icons = {
				pending: '/static/clock.png',
				accepted: '/static/check.png',
				in_progress: '/static/progress.png',
				completed: '/static/success.png',
				cancelled: '/static/cancel.png'
			}
			return icons[this.orderInfo.status] || '/static/clock.png'
		},
		
		statusText() {
			const texts = {
				pending: '待接单',
				accepted: '已接单',
				in_progress: '服务中',
				completed: '已完成',
				cancelled: '已取消'
			}
			return texts[this.orderInfo.status] || '未知状态'
		},
		
		statusDesc() {
			const descs = {
				pending: '等待陪诊师接单',
				accepted: '请按时到达指定地点',
				in_progress: '正在为患者提供陪诊服务',
				completed: '服务已完成，感谢您的专业服务',
				cancelled: '订单已取消'
			}
			return descs[this.orderInfo.status] || ''
		},
		
		showActions() {
			return ['accepted', 'in_progress'].includes(this.orderInfo.status)
		},
		
		mainActionText() {
			const texts = {
				accepted: '开始服务',
				in_progress: '完成服务'
			}
			return texts[this.orderInfo.status] || ''
		}
	},
	
	onLoad(options) {
		if (options.orderId) {
			this.loadOrderDetail(options.orderId)
		}
	},
	
	methods: {
		// 返回
		goBack() {
			uni.navigateBack()
		},
		
		// 加载订单详情
		loadOrderDetail(orderId) {
			try {
				// 从本地存储获取订单列表
				let acceptedOrders = uni.getStorageSync('acceptedOrders') || []
				
				// 查找对应ID的订单
				const order = acceptedOrders.find(item => {
					return String(item.id) === String(orderId)
				})
				
				if (order) {
					// 更新订单信息
				this.orderInfo = {
					...this.orderInfo,
					orderNo: order.orderNo || `PZ${Date.now()}`,
					id: order.id,
					patientName: order.userName || '患者',
					patientAge: order.userAge || 0,
					patientGender: order.userGender || '',
					patientPhone: order.phone || '',
					patientAvatar: order.userAvatar || '/static/avatar1.png',
					serviceType: order.serviceType || '',
					hospital: order.hospitalName || '',
					appointmentTime: order.appointmentTime || '',
					appointmentEndTime: order.appointmentEndTime || '',
					duration: order.duration || '2小时',
					specialRequests: order.specialNote || '',
					serviceFee: order.price || 0,
					platformFee: order.platformFee || 0,
					totalFee: order.price || 0,
					status: order.status || 'accepted',
					serviceRecords: order.serviceRecords || []
				}
					this.isLoading = false
				} else {
					uni.showToast({
						title: '订单不存在',
						icon: 'none'
					})
					setTimeout(() => {
						uni.navigateBack()
					}, 1500)
				}
			} catch (error) {
				console.error('加载订单详情失败:', error)
				this.isLoading = false
				uni.showToast({
					title: '加载失败',
					icon: 'none'
				})
				setTimeout(() => {
					uni.navigateBack()
				}, 1500)
			}
		},
		
		// 联系患者
		contactPatient() {
			uni.showActionSheet({
				itemList: ['拨打电话', '发送消息'],
				success: (res) => {
					if (res.tapIndex === 0) {
						// 拨打电话
						uni.makePhoneCall({
							phoneNumber: this.orderInfo.patientPhone.replace(/\*/g, '')
						})
					} else if (res.tapIndex === 1) {
						// 发送消息
						uni.navigateTo({
							url: `/pages/chat/chat?userId=${this.orderInfo.patientId}&name=${this.orderInfo.patientName}`
						})
					}
				}
			})
		},
		
		// 主要操作
		handleMainAction() {
			if (this.orderInfo.status === 'accepted') {
				this.startService()
			} else if (this.orderInfo.status === 'in_progress') {
				this.completeService()
			}
		},
		
		// 开始服务
		startService() {
			uni.showModal({
				title: '确认开始服务',
				content: `确认已到达指定地点，开始为${this.orderInfo.patientName}提供陪诊服务？`,
				success: (res) => {
					if (res.confirm) {
						// TODO: 调用开始服务API
						this.orderInfo.status = 'in_progress'
						
						// 更新本地存储中的订单状态
						let acceptedOrders = uni.getStorageSync('acceptedOrders') || []
						const orderIndex = acceptedOrders.findIndex(order => order.id == this.orderInfo.id)
						if (orderIndex > -1) {
							acceptedOrders[orderIndex].status = 'in_progress'
							uni.setStorageSync('acceptedOrders', acceptedOrders)
						}
						
						// 通知订单状态更新
						uni.$emit('orderStatusUpdated', {
							orderId: this.orderInfo.id,
							status: 'in_progress'
						})
						
						uni.showToast({
							title: '服务已开始',
							icon: 'success'
						})
					}
				}
			})
		},
		
		// 完成服务
		completeService() {
			uni.showModal({
				title: '确认完成服务',
				content: `确认已完成${this.orderInfo.patientName}的所有陪诊服务？`,
				success: (res) => {
					if (res.confirm) {
						// TODO: 调用完成服务API
						this.orderInfo.status = 'completed'
						
						// 更新本地存储中的订单状态
						let acceptedOrders = uni.getStorageSync('acceptedOrders') || []
						const orderIndex = acceptedOrders.findIndex(order => order.id == this.orderInfo.id)
						if (orderIndex > -1) {
							acceptedOrders[orderIndex].status = 'completed'
							uni.setStorageSync('acceptedOrders', acceptedOrders)
						}
						
						// 通知订单状态更新
						uni.$emit('orderStatusUpdated', {
							orderId: this.orderInfo.id,
							status: 'completed'
						})
						
						// 显示成功提示
						uni.showToast({
							title: '服务已完成',
							icon: 'success',
							duration: 2000
						})
						
						// 延迟跳转到订单页面
						setTimeout(() => {
							uni.switchTab({
								url: '/pages/order/order'
							})
						}, 2000)
					}
				}
			})
		},
		

		
		// 格式化预约时间为时间段
		formatAppointmentTime() {
			if (!this.orderInfo.appointmentTime || !this.orderInfo.appointmentEndTime) {
				return this.orderInfo.appointmentTime || ''
			}
			
			// 将日期字符串转换为iOS兼容格式
			const startTimeStr = this.orderInfo.appointmentTime.replace(/-/g, '/')
			const endTimeStr = this.orderInfo.appointmentEndTime.replace(/-/g, '/')
			
			const startDate = new Date(startTimeStr)
			const endDate = new Date(endTimeStr)
			
			// 格式化日期
			const year = startDate.getFullYear()
			const month = String(startDate.getMonth() + 1).padStart(2, '0')
			const day = String(startDate.getDate()).padStart(2, '0')
			
			// 格式化时间
			const startTime = `${String(startDate.getHours()).padStart(2, '0')}:${String(startDate.getMinutes()).padStart(2, '0')}`
			const endTime = `${String(endDate.getHours()).padStart(2, '0')}:${String(endDate.getMinutes()).padStart(2, '0')}`
			
			return `${year}-${month}-${day} ${startTime}-${endTime}`
		}
	}
}
</script>

